mapper.update:
UPDATE ainer_workspace_member
SET status = 'REVOKED',
    updated_at = GREATEST(updated_at, #{receivedAt})
WHERE tenant_id = #{tenantId}
  AND subject_id = #{subjectId}
  AND status IN ('PENDING', 'ACTIVE')
  AND created_at <= #{occurredAt}

UPDATE ainer_workspace_identity_event_receipt
SET affected_memberships = #{affectedMemberships}
WHERE event_id = #{eventId}

mapper.select:
SELECT affected_memberships
FROM ainer_workspace_identity_event_receipt
WHERE event_id = #{eventId}
